css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; display: grid; place-items: start center; }
.loader .dome { position: relative; width: 84%; height: 78%; overflow: hidden; border-radius: 50%; background: radial-gradient(circle at 34% 26%, rgba(255, 255, 255, .6), color-mix(in srgb, #fff 30%, var(--accent-2)) 46%, color-mix(in srgb, #000 14%, var(--accent-2))); }
.loader .dome::after { content: ''; position: absolute; bottom: 4%; left: 38%; width: 24%; height: 38%; clip-path: polygon(50% 0, 100% 100%, 0 100%); background: linear-gradient(var(--accent), color-mix(in srgb, #000 28%, var(--accent))); }
.loader .dome span { position: absolute; width: 9%; height: 9%; border-radius: 50%; background: rgba(255, 255, 255, .95); animation: snowfall calc(var(--loader-speed) * 2.8) linear infinite; }
.loader .dome span:nth-child(1) { left: 18%; }
.loader .dome span:nth-child(2) { left: 36%; animation-delay: calc(var(--loader-speed) * -.56); }
.loader .dome span:nth-child(3) { left: 52%; animation-delay: calc(var(--loader-speed) * -1.12); }
.loader .dome span:nth-child(4) { left: 68%; animation-delay: calc(var(--loader-speed) * -1.68); }
.loader .dome span:nth-child(5) { left: 82%; animation-delay: calc(var(--loader-speed) * -2.24); }
.loader::after { content: ''; position: absolute; bottom: 2%; left: 18%; width: 64%; height: 17%; border-radius: 4px 4px 9px 9px; background: linear-gradient(color-mix(in srgb, #000 22%, var(--accent-2)), color-mix(in srgb, #000 48%, var(--accent-2))); }
@keyframes snowfall { 0% { opacity: 0; transform: translate(0, -20%); } 12% { opacity: 1; } 88% { opacity: 1; } 100% { opacity: 0; transform: translate(-40%, 320%); } }
